var FT={"Advanced Weapon Proficiency (FS)":{"cat":"G","hb":"GHPG24","d":"Proficiency with Advanced weapons, including their mastery properties.","full":"**Weapon Proficiency.** You have proficiency with Advanced weapons, and your training lets you use the mastery properties of those weapons.","pre":"Fighting Style feature","fx":{"notes":[["Proficiency","Advanced weapons, with their mastery properties (Advanced Weapon Proficiency)"]]}},"Advanced Weapon Proficiency (G)":{"cat":"G","hb":"GHPG24","d":"Proficiency with Advanced weapons, including their mastery properties.","full":"**Weapon Proficiency.** You have proficiency with Advanced weapons, and your training lets you use the mastery properties of those weapons.","pre":"Level 8+","fx":{"notes":[["Proficiency","Advanced weapons, with their mastery properties (Advanced Weapon Proficiency)"]]}},"Blackpowder Pistol Expert":{"cat":"G","hb":"GHPG24","d":"No Disadvantage at long range with a Blackpowder Pistol, ignore its Loading property, and shoot a creature that moves next to you.","full":"Raise Dexterity, Constitution or Intelligence by 1, to a maximum of 20.\n**Deadeye.** Attacking at long range does not impose Disadvantage on your attack rolls with a Blackpowder Pistol.\n**Quick Load.** You ignore the Loading property of the Blackpowder Pistol.\n**Trick Shot.** Right after a creature within 5 feet of you moves, you can use your Reaction to make a ranged attack with a Blackpowder Pistol against it.","pre":"Level 4+","asi":["DEX","CON","INT"]},"Blood Hound":{"cat":"G","hb":"GHPG24","d":"Notice any Small or larger creature that moves within 10 feet. Advantage on Perception checks that rely on sound or smell.","full":"**Motion Sensor.** Whenever a creature of Small size or larger moves within 10 feet of you while you do not have the Unconscious condition, you at once become aware of it.\n**No Hiding.** You have Advantage on Wisdom (Perception) checks that rely on sound or smell.","fx":{"notes":[["Advantage","Wisdom (Perception) checks that rely on sound or smell (Blood Hound)"]]}},"Boon of Magic Resistance":{"cat":"G","hb":"GHPG24","d":"Once between rests, turn a failed saving throw into a success.","full":"Raise Intelligence or Wisdom by 1, to a maximum of 30.\n**Heroic Resistance.** If you fail a saving throw, you can choose to succeed instead. After you use this, finish a Short Rest or Long Rest to do so again.","pre":"Level 19+","asi":["INT","WIS"]},"Boon of Perfect Flight":{"cat":"G","hb":"GHPG24","d":"Fly Speed 40 feet with hovering, and slowed falling.","full":"Raise Strength or Dexterity by 1, to a maximum of 30.\n**Flying.** You have a Fly Speed of 40 feet and can hover.\n**Graceful Fall.** If you fall more than 5 feet, your rate of descent slows to 60 feet per round until you land.","pre":"Level 19+","asi":["STR","DEX"],"fx":{"notes":[["Speed","Fly 40 ft, hover (Boon of Perfect Flight). Falling: 60 ft per round"]]}},"Boon of Shadowsteel Mastery":{"cat":"G","hb":"GHPG24","d":"You are no longer affected by the Friendless.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Strange Bedfellows.** You are no longer affected by the Friendless.","pre":"Level 19+, Shadowsteel Ghoul Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Archlich":{"cat":"G","hb":"GHPG24","d":"Each Long Rest charges an uncharged Soul Vessel with a soul.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Vessel of Vitality.** Whenever you finish a Long Rest, if your Soul Vessel is not charged, it gains a soul and becomes charged.","pre":"Level 19+, Lich Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Ascended Vampire":{"cat":"G","hb":"GHPG24","d":"Sunlight no longer affects you.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Inured to Sunlight.** You are no longer affected by sunlight.","pre":"Level 19+, Vampire Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Earthly Tether":{"cat":"G","hb":"GHPG24","d":"The Fraying Reality no longer affects you. Gain one more Specter Transformation Boon.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Persistent Haunter.** You are no longer affected by the Fraying Reality.\n**Divergent Growth.** Pick any Specter Transformation Boon you do not have yet and whose prerequisites you meet. You gain that Boon.","pre":"Level 19+, Specter Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Elder Fey":{"cat":"G","hb":"GHPG24","d":"The Weakened Constitution no longer affects you. Gain one more Fey Transformation Boon.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Fey Bulwark.** You are no longer affected by the Weakened Constitution.\n**Divergent Growth.** Pick any Fey Transformation Boon you do not have yet and whose prerequisites you meet. You gain that Boon.","pre":"Level 19+, Fey Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Elder Fiend":{"cat":"G","hb":"GHPG24","d":"The Pull of the Netherworld no longer affects you. Gain one more Fiend Transformation Boon.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Free Agent.** You are no longer affected by the Pull of the Netherworld.\n**Divergent Growth.** Pick any Fiend Transformation Boon you do not have yet and whose prerequisites you meet. You gain that Boon.","pre":"Level 19+, Fiend Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Elder Horror":{"cat":"G","hb":"GHPG24","d":"Reroll a low Unstable Form result once per Long Rest. Gain one more Aberrant Horror Transformation Boon.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Stabilizing Form.** When you roll 25 or lower on the Unstable Form, you can roll again and must use the new result. After you use this, finish a Long Rest to do so again.\n**Divergent Growth.** Pick any Aberrant Horror Transformation Boon you do not have yet and whose prerequisites you meet. You gain that Boon.","pre":"Level 19+, Aberrant Horror Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Elemental Temperance":{"cat":"G","hb":"GHPG24","d":"The Primordial Chaos no longer affects you.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Controlled Chaos.** You are no longer affected by the Primordial Chaos.","pre":"Level 19+, Primordial Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the High Seraph":{"cat":"G","hb":"GHPG24","d":"The Seraph Corruption no longer affects you. Gain one more Seraph Transformation Boon.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Absolution.** You are no longer affected by the Seraph Corruption.\n**Divergent Growth.** Pick any Seraph Transformation Boon you do not have yet and whose prerequisites you meet. You gain that Boon.","pre":"Level 19+, Seraph Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Boon of the Wilds":{"cat":"G","hb":"GHPG24","d":"Entering Hybrid Form gives 25 Temporary Hit Points, refreshed at turn end, and Advantage on attacks while you have none.","full":"Raise one ability score of your choice by 1, to a maximum of 30.\n**Apex Predator.** When you enter your Hybrid Form, you gain 25 Temporary Hit Points. At the end of each of your turns in Hybrid Form, if you have no Temporary Hit Points, you gain 10. While you are in Hybrid Form and have no Temporary Hit Points, you have Advantage on attack rolls.","pre":"Level 19+, Lycanthrope Transformation","asi":["STR","DEX","CON","INT","WIS","CHA"]},"Close Combat Artillerist":{"cat":"G","hb":"GHPG24","d":"Enemies within 5 feet do not give Disadvantage on your ranged weapon attacks. +2 damage to adjacent targets you hit at range.","full":"**Firing in Melee.** Having an enemy within 5 feet of you does not impose Disadvantage on your attack rolls with ranged weapons.\n**Point Blank.** When you hit a creature within 5 feet of you with a ranged attack, you gain a +2 bonus to the damage roll.","pre":"Fighting Style feature"},"Convincing Inquisitor":{"cat":"G","hb":"GHPG24","d":"Better odds when you Influence Hostile or Indifferent creatures, any ability for Intimidation or Persuasion, and Initiative edge after spotting a lie.","full":"**Charming Presence.** When you take the Influence action, you do not have Disadvantage on checks to influence Hostile creatures, and you have Advantage on checks to influence Indifferent creatures.\n**Multiple Paths.** When you take the Influence action, you can use any ability modifier for an Intimidation or Persuasion check.\n**Zealous Insight.** When you succeed on a Wisdom (Insight) check made with the Search action to detect lies or evasion, you have Advantage on Initiative rolls for combat against that creature for 1 hour."},"Deathbound":{"cat":"G","hb":"GHPG24","d":"Advantage on Death Saving Throws once you have two failures. Roll Hit Dice twice on a Short Rest and keep the higher roll.","full":"**One Last Breath.** If you have two Death Saving Throw failures, you have Advantage on Death Saving Throws until you are no longer at 0 Hit Points.\n**Recuperation.** When you spend a Hit Point Die during a Short Rest to regain Hit Points, you can roll it twice and use the higher roll."},"Dual Shot":{"cat":"G","hb":"GHPG24","d":"With a bow or crossbow, make one extra attack against a second target within 10 feet of the first. Both attacks have Disadvantage.","full":"**Dual Shot.** When you take the Attack action on your turn and attack with a bow or crossbow, you can make one extra attack as part of that action. It must target a creature within 10 feet of the original target, and that creature must be within the weapon's range. Both attacks are made with Disadvantage.","pre":"Fighting Style feature"},"Expanded Grip":{"cat":"G","hb":"GHPG24","d":"Use Versatile weapons one-handed with the larger damage die. Advantage to keep hold of your weapon, and a DC 15 Strength save when forced to drop it.","full":"Raise Strength, Dexterity or Constitution by 1, to a maximum of 20.\n**One-Handed Grip.** When you wield a Versatile weapon in one hand, it deals the damage listed in parentheses when you make a melee attack with it.\n**Zealous Grasp.** If an effect forces you to drop what you are holding, you can make a DC 15 Strength saving throw to keep your grip. When an effect lets you make a saving throw to keep your grip, you have Advantage on it.","pre":"Level 4+, Str 13+","asi":["STR","DEX","CON"]},"Flurry":{"cat":"G","hb":"GHPG24","d":"Once per turn, drop Advantage on an attack to make another attack with the same weapon against a different nearby creature.","full":"**Quick Strike.** Once on each of your turns, when you make an attack roll with a weapon or an Unarmed Strike and have Advantage on it, you can give up that Advantage. After the attack resolves, you can make another attack with the same weapon or Unarmed Strike against a different creature. The new target must be within 5 feet of the first one and within the weapon's reach.","pre":"Fighting Style feature"},"Fortune of the Thaumaturge":{"cat":"G","hb":"GHPG24","d":"After failing a D20 Test, spend and roll a Hit Die and add it. Proficiency Bonus times per Long Rest. Max or min rolls refund the die.","full":"**Fortune's Fortitude.** When you fail a D20 Test, you can spend and roll one Hit Point Die and add the number to the result. You can do this only once per D20 Test, a number of times equal to your Proficiency Bonus. You regain all uses when you finish a Long Rest.\n**Fortune of the Unknown.** When you use Fortune's Fortitude and roll the highest or lowest number on the die, you regain that Hit Point Die. The use still counts."},"Free Sword Mercenary's Will":{"cat":"G","hb":"GHPG24","d":"Reaction: cut the distance a creature moves you by up to your Speed. Advantage on saves that would inflict a condition.","full":"**Hold the Ground.** When a creature moves you without using your own movement, you can use your Reaction to reduce the distance you are moved by up to your Speed.\n**Resolute.** You have Advantage on saving throws that would apply a condition.","fx":{"notes":[["Advantage","Saving throws that would apply a condition (Free Sword Mercenary's Will)"]]}},"Hulking Figure":{"cat":"G","hb":"GHPG24","d":"Extra 1d4 Bludgeoning on an Unarmed Strike each turn, add Strength to some Charisma checks, and count as one size larger for carrying capacity.","full":"Raise Strength or Constitution by 1, to a maximum of 20.\n**Brutal.** Once per turn, you can deal an extra 1d4 Bludgeoning damage to a target you hit with an Unarmed Strike.\n**Intimidating.** When you make a Charisma (Intimidation, Performance or Persuasion) check, you can also add your Strength modifier to the roll.\n**Powerful.** You count as one size larger, to a maximum of Large, when determining your carrying capacity.","pre":"Level 4+, Str 13+","asi":["STR","CON"]},"Insightful Collector":{"cat":"G","hb":"GHPG24","d":"Study a magic item to learn its properties without attuning (with a chance of error). You start with a Common magic item.","full":"**Object Intuition.** You can take the Study action to examine one magic item and learn its properties and how to use it, without attuning to it or spending a Short Rest touching it. You do not learn any curse on the item. For every rarity step above Common, there is a cumulative 5 percent chance you misjudge the item's nature and power.\n**Rare Find.** You begin play with a Common magic item. Work with your GM to choose one that fits your character and the campaign."},"Iron Gut":{"cat":"G","hb":"GHPG24","d":"Advantage to avoid or end Poisoned and to forage for food. Bonus Action: spend a Hit Point Die to heal, once per Short or Long Rest.","full":"Raise Strength, Constitution or Charisma by 1, to a maximum of 20.\n**Inured to Poison.** You have Advantage on saving throws to avoid or end the Poisoned condition.\n**Everything Looks Delicious.** You have Advantage on Wisdom (Survival) checks made to forage for food.\n**Quick to Recover.** As a Bonus Action, you can spend one of your Hit Point Dice, roll it, add your Constitution modifier, and regain Hit Points equal to the total. After you use this, finish a Short Rest or Long Rest to do so again.","pre":"Level 4+, Con 13+","asi":["STR","CON","CHA"],"fx":{"notes":[["Advantage","Saves to avoid or end Poisoned, and Wisdom (Survival) checks to forage (Iron Gut)"]]}},"Lightning Caster":{"cat":"G","hb":"GHPG24","d":"Hit a second target with a one-action cantrip using a Bonus Action. Cast a Reaction spell with no slot once per Long Rest.","full":"Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Dual Target.** When you cast a cantrip that takes an action to cast and targets a single creature, you can use a Bonus Action to target a second creature within the cantrip's range.\n**Immediate Response.** When you cast a spell as a Reaction, it does not expend a spell slot. After you use this, finish a Long Rest to do so again.","pre":"Level 4+, Spellcasting","asi":["INT","WIS","CHA"]},"Medician of the Morbus Doctore":{"cat":"G","hb":"GHPG24","d":"Improves Triage Expert: the creature can spend up to three Hit Dice, or spend three to end a condition or a Grievous Wound.","full":"**Adept Medic.** When you use the Blood and Bone benefit of the Triage Expert feat, the creature can spend up to three Hit Point Dice instead of one.\n**Battle Surgeon.** When you use the Blood and Bone benefit of the Triage Expert feat, the creature can spend three Hit Point Dice to end one of these conditions on itself instead of regaining Hit Points: Blinded, Deafened, Paralyzed, Poisoned or Stunned. You can instead cure one Grievous Wound affecting the creature.","pre":"Level 4+, Triage Expert feat"},"Mobile Combatant":{"cat":"G","hb":"GHPG24","d":"When you take the Attack action, your Speed rises by 10 feet and Opportunity Attacks against you have Disadvantage until the end of your turn.","full":"**Slippery.** When you take the Attack action, your Speed increases by 10 feet, and Opportunity Attacks made against you have Disadvantage until the end of your turn.","pre":"Fighting Style feature"},"Nimble Physique":{"cat":"G","hb":"GHPG24","d":"Without armor or a Shield, Dodge as a Bonus Action. Being Grappled or Restrained does not hamper your attacks or help attackers.","full":"Raise Strength, Dexterity or Constitution by 1, to a maximum of 20.\n**Dodgy.** While you are not wearing armor or wielding a Shield, you can take the Dodge action as a Bonus Action.\n**Slippery.** While you have the Grappled or Restrained condition, your attacks do not have Disadvantage and attacks against you do not have Advantage because of it.","pre":"Level 4+, Dex 13+","asi":["STR","DEX","CON"]},"Opportunist (Grim Hollow)":{"cat":"G","hb":"GHPG24","d":"+2 to attack and damage rolls for attacks you make as part of a Reaction.","full":"**Exploit Weakness.** Whenever you make an attack as part of a Reaction, you gain a +2 bonus to the attack roll and the damage roll.","pre":"Fighting Style feature"},"Prone Defense":{"cat":"G","hb":"GHPG24","d":"Being Prone no longer gives you Disadvantage on attacks or gives attackers Advantage. Stand up for only 5 feet of movement.","full":"**Defensive.** While you have the Prone condition, you do not have Disadvantage on attack rolls, and attack rolls against you do not gain Advantage from the Prone condition.\n**Hop Up.** While you have the Prone condition, you can stand up by spending only 5 feet of movement.","pre":"Fighting Style feature"},"Resolution of the Syndicate":{"cat":"G","hb":"GHPG24","d":"First damage roll after Initiative adds 1d4 (2d4 at level 9, 4d4 at level 16). Hit Point maximum +1 per level, starting with your level.","full":"**Quick Strike.** On your first turn after an Initiative roll, add 1d4 to the first damage roll you make. The extra damage becomes 2d4 at character level 9 and 4d4 at character level 16.\n**Resilient.** Your Hit Point maximum increases by your character level when you gain this feat. Each time you gain a level after that, it increases by 1 more."},"Sangromantic Initiate":{"cat":"G","hb":"GHPG24","d":"Pick a Sangromancy spell, always prepared, cast once per Long Rest free. Pool of two d12s to fuel Sangromancy spells.","full":"**Blood Magic.** Choose a Sangromancy spell from any spell list, of a level for which you have spell slots. You always have it prepared. You can cast it once without a spell slot, and you regain that ability when you finish a Long Rest. You can also cast it with any spell slot you have.\n**Sanguine Potency.** You have a pool of two d12s that you can spend instead of Hit Point Dice when you cast Sangromancy spells. The pool refills when you finish a Long Rest.","pre":"Level 4+, Spellcasting"},"Shadowsteel Adept":{"cat":"G","hb":"GHPG24","d":"Shadowsteel curses always prepared. +1 to spell attacks and save DCs while holding your Shadowsteel Focus, and +1 to a Focus weapon.","full":"Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Curse Caster.** You always have the Shadowsteel curses prepared, and you can cast them with any spell slots you have.\n**Shadowsteel's Bite.** While you hold your Shadowsteel Focus, you gain a +1 bonus to spell attack rolls and to the saving throw DCs of your spells.\n**Shadowsteel Weapon.** If your Shadowsteel Focus is also a weapon, it has a +1 bonus to attack rolls and damage rolls.","pre":"Level 4+, Spellcasting","asi":["INT","WIS","CHA"]},"Shadowsteel Master":{"cat":"G","hb":"GHPG24","d":"Focus bonus rises: +2 to a Focus weapon and an extra 2d8 Necrotic once per turn. Spells you cast with a Focus can add 1d4 Necrotic per slot level.","full":"Raise Intelligence, Wisdom or Charisma by 1, to a maximum of 20.\n**Necrotic Harmony.** While you hold your Shadowsteel Focus and cast a spell that targets creatures and needs an attack roll or a saving throw, you can pick one target you hit or that failed its save. It also takes 1d4 Necrotic damage for each level of the spell slot used to cast the spell.\n**Necrotic Weapon.** If your Shadowsteel Focus is also a weapon, its bonus to attack rolls and damage rolls is +2. Also, once on each of your turns when you hit with a weapon attack using your Focus, you can deal an extra 2d8 Necrotic damage to the target.","pre":"Level 8+, Shadowsteel Adept feat","asi":["INT","WIS","CHA"]},"Survivor (Grim Hollow)":{"cat":"G","hb":"GHPG24","d":"Half the usual food per day. Advantage on Intelligence checks made with the Study action. Short Rest lowers Exhaustion by 1, Long Rest by 2.","full":"**Hardy.** You need only half the food per day that your size normally requires.\n**Intuitive.** When you take the Study action, you have Advantage on the Intelligence check.\n**Shake It Off.** Whenever you finish a Short Rest, your Exhaustion level, if any, drops by 1. When you finish a Long Rest, it drops by 2.","fx":{"notes":[["Note","Survivor: a Short Rest lowers Exhaustion by 1, a Long Rest by 2"]]}},"Syndicate Spy":{"cat":"G","hb":"GHPG24","d":"Thieves' Tools, Disguise Kit and Forgery Kit proficiency, craft keys, perfect disguises, and Charisma to Hide from non-hostile creatures.","full":"**Locksmith.** You have proficiency with Thieves' Tools. While holding them, you can craft a key to a lock by spending 10 minutes with that lock.\n**Master of Disguise.** You have proficiency with the Disguise Kit. If you spend 10 minutes donning a Costume, you decide your look, including height, weight, facial features, voice, hair length, coloring and other traits. You can appear as a member of another species, though your statistics do not change. You cannot change size, and your basic shape stays the same (a biped cannot become a quadruped).\n**Master Calligrapher.** You have proficiency with the Forgery Kit. When you mimic someone's handwriting you are not limited to 10 words.\n**Blending In.** When you take the Hide action against creatures that are not Hostile to you, you need only be Lightly Obscured, and you can use Charisma instead of Dexterity for the check.","pre":"Level 4+, Syndicate Smuggler background","fx":{"notes":[["Tools","Thieves' Tools, Disguise Kit, Forgery Kit (Syndicate Spy)"]]}},"Thrown Weapon Master":{"cat":"G","hb":"GHPG24","d":"Make two extra thrown attacks with Simple Thrown weapons as a Bonus Action, retrieve them fast, and give them the Returning mastery.","full":"Raise Strength or Dexterity by 1, to a maximum of 20.\n**Multithrow.** After you take the Attack action and make a ranged attack with a Simple weapon that has the Thrown property, you can make two more ranged attacks with Simple weapons that have the Thrown property as a Bonus Action.\n**Quick Hands.** As a Bonus Action, you can pick up and stow or wield every Simple weapon with the Thrown property within 5 feet of you. You need a free hand.\n**Returning.** Simple weapons with the Thrown property that you are proficient with also have the Returning mastery property.","pre":"Level 4+, Str 13+ and Dex 13+","asi":["STR","DEX"]},"Triage Expert":{"cat":"G","hb":"GHPG24","d":"Use a Healer's Kit charge to let a nearby creature spend a Hit Die to heal. Roll an extra die and drop the lowest on healing.","full":"**Bedside Manner.** Whenever a creature regains Hit Points because of you, or through Blood and Bone, you can roll one extra die and discard the lowest die.\n**Blood and Bone.** When you take the Utilize action and spend a use of a Healer's Kit, you can heal a creature within 5 feet of you. The creature can spend and roll one Hit Point Die and regain Hit Points equal to the roll."},"Witch Hunter":{"cat":"G","hb":"GHPG24","d":"Reaction: Wisdom save to turn aside a single-target spell. Cut the Speed of spellcasters you hit. Advantage against curses and long spells.","full":"Raise Strength, Constitution or Wisdom by 1, to a maximum of 20.\n**Dodge Spells.** You can use your Reaction to avoid a spell that targets only you and has no area of effect. Make a Wisdom saving throw against the caster's spell save DC. On a success, the caster must choose a new target or the spell is canceled. A canceled spell fizzles and the resources spent on it are lost.\n**Keep Your Enemies Close.** When you hit a creature that can cast spells with a melee weapon attack or an Unarmed Strike, you can reduce its Speed by 15 feet until the start of your next turn.\n**Resist Curses.** You have Advantage on saving throws against all Shadowsteel curses and against spells with a duration longer than 10 minutes.","pre":"Level 4+","asi":["STR","CON","WIS"],"fx":{"notes":[["Advantage","Saves against Shadowsteel curses and spells lasting over 10 minutes (Witch Hunter)"]]}}};
var FTLU=[{"src":"feat","owner":"Boon of Magic Resistance","feature":"Boon of Magic Resistance","n":"Heroic Resistance","lvl":1,"max":1,"reset":"short","tag":"Failed save"},{"src":"feat","owner":"Boon of the Elder Horror","feature":"Boon of the Elder Horror","n":"Stabilizing Form","lvl":1,"max":1,"reset":"long","tag":"Reroll"},{"src":"feat","owner":"Fortune of the Thaumaturge","feature":"Fortune of the Thaumaturge","n":"Fortune's Fortitude","lvl":1,"max":"pb","reset":"long","tag":"Failed D20 Test"},{"src":"feat","owner":"Iron Gut","feature":"Iron Gut","n":"Quick to Recover","lvl":1,"max":1,"reset":"short","tag":"Bonus Action"},{"src":"feat","owner":"Lightning Caster","feature":"Lightning Caster","n":"Immediate Response","lvl":1,"max":1,"reset":"long","tag":"Reaction spell"},{"src":"feat","owner":"Sangromantic Initiate","feature":"Sangromantic Initiate","n":"Blood Magic (free cast)","lvl":1,"max":1,"reset":"long","tag":"Spell"}];
